mapper.insert:
WITH chkUpdate AS (
                    UPDATE ics33_compliance_answer
                       SET ics33_compliance_type = #{complianceType}
                     WHERE ics33_company_id      = #{companyId}
                       AND ics33_compliance_type = #{complianceType}
                       AND ics33_start_date      = #{startDate}
                 RETURNING *
                  )
INSERT INTO ics33_compliance_answer
       ( ics33_compliance_answer_id, ics33_company_id, ics33_start_date, ics33_compliance_type, ics33_case_no,
         ics33_answer1_cd, ics33_answer2_cd, ics33_answer3_cd, ics33_answer4_cd, ics33_answer5_cd )
SELECT f_create_seq()
     , ics33_company_id
     , #{startDate}
     , ics33_compliance_type
     , ics33_case_no
     , ics33_answer1_cd
     , ics33_answer2_cd
     , ics33_answer3_cd
     , ics33_answer4_cd
     , ics33_answer5_cd
  FROM ics33_compliance_answer
 WHERE ics33_company_id      = #{companyId}
   AND ics33_compliance_type = #{complianceType}
   AND ics33_start_date      = ( SELECT MAX(a.ics33_start_date)
                                   FROM ics33_compliance_answer a
                                  WHERE a.ics33_company_id      = #{companyId}
                                    AND a.ics33_compliance_type = #{complianceType}
                                    AND a.ics33_start_date  <=  #{startDate} )
   AND NOT EXISTS (SELECT * FROM chkUpdate)

